/bin/bash -lc "cat > src/util/ordersApi.mjs <<'EOF'
// Normalizes the backend's order-list response (loaded by src/pages/other/RecentOrder.js)
// into a plain { orders, pages, total, onThisPage } shape.

const toNumber = (value) => {
  const n = Number(value);
  return Number.isFinite(n) ? n : 0;
};

export function normalizeOrderList(response) {
  const source = response && typeof response === \"object\" ? response : {};
  const orders = Array.isArray(source.orders) ? source.orders : [];

  return {
    orders,
    pages: toNumber(source.totalPages),
    total: toNumber(source.recordsTotal),
    onThisPage: toNumber(source.recordsOnPage),
  };
}
EOF
